package com.hotelmanagement.hms.payment.model;
import com.hotelmanagement.hms.shared.model.BranchEntity; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*;
@Entity @Table(name="cashier_shifts") public class CashierShift extends BranchEntity { @Column(name="cashier_user_id",nullable=false) UUID cashierUserId; @Column(name="opened_at",nullable=false) Instant openedAt; Instant closedAt; @Column(name="opening_float",nullable=false) BigDecimal openingFloat; BigDecimal expectedAmount,countedAmount,difference; @Enumerated(EnumType.STRING) @Column(nullable=false) CashierShiftStatus status; String notes; protected CashierShift(){} public static CashierShift open(UUID h,UUID b,UUID u,BigDecimal f,String n){var s=new CashierShift();s.hotelId=h;s.branchId=b;s.cashierUserId=u;s.openedAt=Instant.now();s.openingFloat=f;s.status=CashierShiftStatus.OPEN;s.notes=n;return s;} public Instant getOpenedAt(){return openedAt;} public UUID getCashierUserId(){return cashierUserId;} public CashierShiftStatus getStatus(){return status;} public BigDecimal getOpeningFloat(){return openingFloat;} public BigDecimal getExpectedAmount(){return expectedAmount;} public BigDecimal getCountedAmount(){return countedAmount;} public BigDecimal getDifference(){return difference;} public void close(BigDecimal expected,BigDecimal counted){if(status!=CashierShiftStatus.OPEN)throw new IllegalStateException("Shift is not open.");closedAt=Instant.now();expectedAmount=expected;countedAmount=counted;difference=counted.subtract(expected);status=CashierShiftStatus.CLOSED;} public void reconcile(){if(status!=CashierShiftStatus.CLOSED)throw new IllegalStateException("Shift must be closed first.");status=CashierShiftStatus.RECONCILED;} }

